<?php
require 'team_bootstrap.php'; require_role('faculty');
$title='Class Teams';$fid=(int)$_SESSION['user']['id'];
$q=$pdo->prepare("SELECT ct.id team_id,o.id offering_id,s.code,s.name,s.units,o.section,o.day_name,o.start_time,o.end_time,o.room,COUNT(DISTINCT e.student_id) student_count FROM course_teams ct JOIN subject_offerings o ON o.id=ct.offering_id JOIN subjects s ON s.id=o.subject_id LEFT JOIN enrollments e ON e.offering_id=o.id AND e.status='approved' WHERE o.faculty_id=? GROUP BY ct.id,o.id,s.id,o.section,o.day_name,o.start_time,o.end_time,o.room ORDER BY s.code,o.section");$q->execute([$fid]);$teams=$q->fetchAll();require 'header.php';
?><section class="section"><div class="section-intro"><div><span class="eyebrow">FACULTY CLASS HUB</span><h2>Class Teams</h2><p class="muted">Manage assignments and online group meetings for each subject you teach.</p></div></div><div class="team-grid"><?php foreach($teams as $t):?><a class="team-card" href="faculty_team.php?team=<?=e($t['team_id'])?>"><div class="team-card-top"><span class="team-icon">T</span><span class="team-code"><?=e($t['code'])?></span></div><h3><?=e($t['name'])?></h3><p>Section <?=e($t['section'])?> · <?=e($t['units'])?> units</p><div class="team-meta"><span><?=e($t['student_count'])?> students</span><span><?=e($t['room'])?></span></div><div class="team-schedule"><?=e($t['day_name'])?> · <?=date('g:i A',strtotime($t['start_time']))?>–<?=date('g:i A',strtotime($t['end_time']))?></div><b class="team-open">Manage Team →</b></a><?php endforeach;?></div><?php if(!$teams):?><p class="muted">No teaching teams are currently assigned to you.</p><?php endif;?></section><?php require 'footer.php';?>
